<body>
    <div id="app-container" class="container-all">
        <div style="text-align: center; padding: 50px; font-family: var(--font-main); color: var(--primary-glow);">
            正在等待ERA数据加载</div>
    </div>
    <div id="modal-container"></div>
    <script>
        document.addEventListener('DOMContentLoaded', function () {
            function getPhysiologicalStatus(physiologicalData) {
                if (!physiologicalData) {
                    return { text: '未知', className: '' };
                }

                if (physiologicalData['怀孕状态'] && physiologicalData['怀孕状态'] !== "未怀孕") {
                    return { text: physiologicalData['怀孕状态'], className: 'status-pregnancy' };
                }
                if (physiologicalData['是否生理期']) {
                    return { text: '生理期', className: 'status-period' };
                }
                if (physiologicalData['安全期']) {
                    return { text: '安全期', className: 'status-safe' };
                }
                return { text: '危险期', className: 'status-danger' };
            }
            const charColors = ['#9cdcfe', '#c586c0', '#6a9955', '#ce9178', '#d16969', '#dcdcaa'];
            const appContainer = document.getElementById('app-container');

            // --- 添加女性卡片 ---
            function renderMainPanel(mainInfo, worldData) {
                const isFemaleUser = mainInfo?.['性别'] !== '男';

                const userCardTriggerHTML = isFemaleUser
                    ? `<button class="user-card-trigger" id="user-card-trigger-btn">查看个人档案</button>`
                    : '';

                appContainer.innerHTML = `
                 <div class="main-status-panel">
                    <h2>{{user}}状态总览 ${userCardTriggerHTML}</h2>
                    <div class="status-grid">
                        <div class="status-item"><span class="label">时间:</span><span class="value">${worldData?.['时间'] || '...'}</span></div>
                        <div class="status-item"><span class="label">职业:</span><span class="value">${mainInfo?.['职业'] || '...'}</span></div>
                        <div class="status-item"><span class="label">余额:</span><span class="value">${mainInfo?.['余额'] || '...'}</span></div>
                        <div class="status-item" style="grid-column: 1 / -1;"><span class="label">当前穿着:</span><span class="value">${mainInfo?.['穿着'] || '...'}</span></div>
                        <div class="status-item" style="grid-column: 1 / -1;"><span class="label">当前姿势:</span><span class="value">${mainInfo?.['姿势'] || '...'}</span></div>
                    </div>
                </div>
                <h2 class="scene-title">- 在场人物 -</h2>
                <div id="characters-container" class="characters-container"></div>`;

                if (isFemaleUser) {
                    document.getElementById('user-card-trigger-btn')?.addEventListener('click', () => {
                        showUserModal(mainInfo);
                    });
                }
            }


            function renderBriefCards(allCharacters) {
                const container = document.getElementById('characters-container');
                if (!container) return;
                container.innerHTML = '';
                const presentCharacters = allCharacters.filter(char => char['实时状态']?.['是否在场'] === true);
                if (presentCharacters.length === 0) {
                    // container.innerHTML = `<div style="text-align:center; color: var(--text-secondary);">当前场景无其他人物。</div>`
                    return;
                }
                presentCharacters.forEach((charData, index) => {
                    const card = document.createElement('div');
                    card.className = 'character-card-brief';
                    card.style.animationDelay = `${index * 0.1}s`;
                    const color = charColors[index % charColors.length];
                    const status = getPhysiologicalStatus(charData['生理状态']);
                    card.style.borderLeftColor = color;
                    card.dataset.characterData = JSON.stringify(charData);
                    card.dataset.charIndex = index;
                    card.innerHTML = `<div class="brief-header"><div><div class="name">${charData['基础信息']?.['姓名'] || '未知'} <span class="physio-status-badge ${status.className}">${status.text}</span></div><div class="subtitle">${charData['基础信息']?.['职业'] || ''} - ${charData['基础信息']?.['年龄'] || '?'}</div></div></div><div class="brief-info"><div class="brief-info-item"><span class="label">内心想法:</span><span class="value thought-value">${charData['实时状态']?.['心理活动'] || "..."}</span></div><div class="brief-info-item"><span class="label">当前姿势:</span><span class="value pose-value">${charData['实时状态']?.['当前姿势'] || "..."}</span></div></div>`;
                    card.addEventListener('click', () => showModal(card.dataset.characterData, parseInt(card.dataset.charIndex)));
                    container.appendChild(card);
                });
            }


            function showModal(charDataString, index) {
                const char = JSON.parse(charDataString);
                if (!char) return;
                const color = charColors[index % charColors.length];
                const modalContainer = document.getElementById('modal-container');
                const physiologicalData = char['生理状态'] || {};
                if (!modalContainer) return;
                const modalDiv = document.createElement('div');
                modalDiv.className = 'modal-overlay';
                modalDiv.id = 'modal-overlay';
                modalDiv.innerHTML = `<div class="modal-content"><div class="modal-header" style="border-bottom-color: ${color};"><h3 class="name" style="text-shadow: 0 0 10px ${color};">${char['基础信息']?.['姓名'] || 'N/A'}</h3><p class="subtitle">${char['基础信息']?.['职业'] || 'N/A'} - ${char['基础信息']?.['年龄'] || 'N/A'}</p></div><div class="modal-body"><div class="info-content"><ul class="info-list"><li class="info-list-item"><strong>身高:</strong> ${char['外貌特征']?.['身高'] || 'N/A'}</li><li class="info-list-item"><strong>颜值:</strong> ${char['外貌特征']?.['颜值等级'] || 'N/A'}</li><li class="info-list-item"><strong>身材:</strong> ${char['外貌特征']?.['身材'] || 'N/A'}</li><li class="info-list-item"><strong>风格:</strong> ${char['外貌特征']?.['穿着风格'] || 'N/A'}</li><li class="info-list-item"><strong>饰品:</strong> ${char['外貌特征']?.['随身饰品'] || 'N/A'}</li><li class="info-list-item"><strong>印记:</strong> ${char['外貌特征']?.['身体印记'] || 'N/A'}</li><li class="info-list-item" style="border-top:1px solid var(--border-color);margin-top:10px;padding-top:10px;"><strong>存款:</strong> ${char['基础信息']?.['存款'] || 'N/A'}</li><li class="info-list-item"><strong>债务:</strong> ${char['社会关系']?.['债务状况'] || 'N/A'}</li><li class="info-list-item"><strong>交往-性交:</strong> ${char['社会关系']?.['交往人数'] || 'N/A'} - ${char['社会关系']?.['性交人数'] || 'N/A'}</li><li class="info-list-item"><strong>怀孕经历:</strong> ${char['社会关系']?.['怀孕经历'] || 'N/A'}</li><li class="info-list-item"><strong>收入来源:</strong> ${char['社会关系']?.['收入来源'] || 'N/A'}</li><li class="info-list-item"><strong>社交网络:</strong> ${char['社会关系']?.['社交网络'] || 'N/A'}</li></ul>
                    <details class="collapsible-section"><summary class="collapsible-title">生理状态详情</summary><ul class="info-list"><li class="info-list-item"><strong>是否生理期:</strong> ${physiologicalData['是否生理期'] ? '是' : '否'}</li><li class="info-list-item"><strong>生理周期天数:</strong> ${physiologicalData['生理周期天数'] || 'N/A'}</li><li class="info-list-item"><strong>下次生理期:</strong> ${physiologicalData['距离下次生理期天数'] === -1 ? '无 (怀孕中)' : `还剩 ${physiologicalData['距离下次生理期天数']} 天`}</li><li class="info-list-item"><strong>生理期持续:</strong> ${physiologicalData['生理期持续天数'] || 'N/A'} 天</li><li class="info-list-item"><strong>怀孕状态:</strong> ${physiologicalData['怀孕状态'] || 'N/A'}</li><li class="info-list-item"><strong>怀孕天数:</strong> ${physiologicalData['怀孕天数'] || 'N/A'}</li><li class="info-list-item"><strong>安全期状态:</strong> ${physiologicalData['安全期'] ? '是' : '否'}</li><li class="info-list-item"><strong>堕胎次数:</strong> ${physiologicalData['堕胎次数']}</li><li class="info-list-item"><strong>生育次数:</strong> ${physiologicalData['生育次数']}</li></ul></details>
                    </div></div></div>`;
                modalContainer.appendChild(modalDiv);
                void modalDiv.offsetWidth;
                modalDiv.classList.add('active');
                modalDiv.addEventListener('click', function (e) { if (e.target === this) { this.classList.remove('active'); this.addEventListener('transitionend', () => this.remove(), { once: true }); } });
            }

            function showUserModal(userData) {
                if (!userData) return;
                const color = 'var(--user-glow)';
                const modalContainer = document.getElementById('modal-container');
                if (!modalContainer) return;

                const appearanceData = userData['外貌特征'] || {};
                const physiologicalData = userData['生理状态'] || {};
                const socialData = userData['社会关系'] || {};

                const modalDiv = document.createElement('div');
                modalDiv.className = 'modal-overlay';
                modalDiv.id = 'modal-overlay-user';
                modalDiv.innerHTML = `
                    <div class="modal-content">
                        <div class="modal-header" style="border-bottom-color: ${color};">
                            <h3 class="name" style="text-shadow: 0 0 10px ${color};"> {{user}}</h3>
                            <p class="subtitle">${userData['职业'] || 'N/A'}</p>
                        </div>
                        <div class="modal-body">
                               <div class="info-content">
                                <ul class="info-list">
                                    <li class="info-list-item"><strong>身高:</strong> ${appearanceData['身高'] || 'N/A'}</li>
                                    <li class="info-list-item"><strong>身材:</strong> ${appearanceData['身材'] || 'N/A'}</li>
                                    <li class="info-list-item"><strong>颜值等级:</strong> ${appearanceData['颜值等级'] || 'N/A'}</li>
                                    <li class="info-list-item"><strong>随身饰品:</strong> ${appearanceData['随身饰品'] || 'N/A'}</li>
                                    <li class="info-list-item"><strong>身体印记:</strong> ${appearanceData['身体印记'] || 'N/A'}</li>
                                    <li class="info-list-item" style="border-top:1px solid var(--border-color);margin-top:10px;padding-top:10px;"><strong>债务状况:</strong> ${socialData['债务状况'] || 'N/A'}</li>
                                    <li class="info-list-item"><strong>收入来源:</strong> ${socialData['收入来源'] || 'N/A'}</li>
                                    <li class="info-list-item"><strong>交往人数:</strong> ${socialData['交往人数'] || '0'}</li>
                                    <li class="info-list-item"><strong>性交人数:</strong> ${socialData['性交人数'] || '0'}</li>
                                    <li class="info-list-item"><strong>怀孕经历:</strong> ${socialData['怀孕经历'] || 'N/A'}</li>
                                    <li class="info-list-item"><strong>社交网络:</strong> ${socialData['社交网络'] || 'N/A'}</li>
                                </ul>
                                <details class="collapsible-section">
                                    <summary class="collapsible-title">生理状态详情 (点击展开)</summary>
                                    <ul class="info-list">
                                        <li class="info-list-item"><strong>是否生理期:</strong> ${physiologicalData['是否生理期'] ? '是' : '否'}</li>
                                        <li class="info-list-item"><strong>生理周期:</strong> ${physiologicalData['生理周期天数'] || 'N/A'} 天</li>
                                        <li class="info-list-item"><strong>下次生理期:</strong> ${physiologicalData['距离下次生理期天数'] === -1 ? '无 (怀孕中)' : `还剩 ${physiologicalData['距离下次生理期天数']} 天`}</li>
                                        <li class="info-list-item"><strong>持续时间:</strong> ${physiologicalData['生理期持续天数'] || 'N/A'} 天</li>
                                        <li class="info-list-item"><strong>怀孕状态:</strong> ${physiologicalData['怀孕状态'] || 'N/A'}</li>
                                        <li class="info-list-item"><strong>怀孕天数:</strong> ${physiologicalData['怀孕天数'] || 'N/A'}</li>
                                        <li class="info-list-item"><strong>安全期:</strong> ${physiologicalData['安全期'] ? '是' : '否'}</li>
                                        <li class="info-list-item"><strong>堕胎次数:</strong> ${physiologicalData['堕胎次数']}</li>
                                        <li class="info-list-item"><strong>生育次数:</strong> ${physiologicalData['生育次数']}</li>
                                    </ul>
                                </details>
                            </div>
                        </div>
                    </div>`;

                modalContainer.appendChild(modalDiv);
                void modalDiv.offsetWidth;
                modalDiv.classList.add('active');
                modalDiv.addEventListener('click', function (e) {
                    if (e.target === this) {
                        this.classList.remove('active');
                        this.addEventListener('transitionend', () => this.remove(), { once: true });
                    }
                });
            }

            function renderCycle(waitForData) {
                setLoadingState("正在等待ERA数据加载...");
                try {
                    const data = waitForData;
                    if (data && data['世界'] && data['user']) {
                        const worldData = data['世界'] || {};
                        const mainInfoData = data['user'] || {};
                        const allCharacters = data['精神小妹'] ? Object.values(data['精神小妹']) : [];
                        renderMainPanel(mainInfoData, worldData);
                        renderBriefCards(allCharacters);
                    } else {
                        throw new Error("未能获取到完整数据。");
                        setFailureState();
                    }
                } catch (error) {
                    console.error(error.message);
                    setFailureState();
                }
            }

            function setLoadingState(message) {
                appContainer.innerHTML = `<div style="text-align: center; padding: 50px; font-family: var(--font-main); color: var(--primary-glow);">${message}</div>`;
            }

            function setFailureState() {
                appContainer.innerHTML = `
                    <div style="text-align: center; padding: 50px 20px; font-family: var(--font-main); color: #ff4d4d;">
                        ERA系统连接失败...<br><small style="color:var(--text-secondary);font-size:0.8em;font-weight:400;">有可能是ERA变量输出格式不正确，检查一下ERA变量，或者从ROLL</small>
                    </div>
                    <div style="text-align:center; padding-bottom: 20px;">
                        <button id="retry-button">↻ 重试连接</button>
                    </div>`;
                const retryButton = document.getElementById('retry-button');
                if (retryButton) {
                    retryButton.onclick = () => {
                        retryButton.textContent = '↻ 正在重试...';
                        retryButton.disabled = true;
                        eventEmit('era:requestWriteDone');
                    };
                }
            }

            eventOn('era:writeDone', (detail) => {
                console.log('ERA:writeDone event received:', detail);
                if (detail && detail.statWithoutMeta) {
                    renderCycle(detail.statWithoutMeta);
                } else {
                    console.warn('era:writeDone event did not contain expected data structure.');
                    // 可以在这里调用失败处理
                    setFailureState();
                }
            });


            console.log('Requesting initial ERA variables...');
            eventEmit('era:requestWriteDone');
        });

    </script>
</body>

</html>
