</div>
<script>
    const HEART_HOLLOW_PATH = 'm8 2.748-.717-.737C5.6.281 2.514.878 1.4 3.053c-.523 1.023-.641 2.5.314 4.385.92 1.815 2.834 3.989 6.286 6.357 3.452-2.368 5.365-4.542 6.286-6.357.955-1.886.838-3.362.314-4.385C13.486.878 10.4.28 8.717 2.01L8 2.748zM8 15C-7.333 4.868 3.279-3.04 7.824 1.143c.06.055.119.112.176.171a3.12 3.12 0 0 1 .176-.17C12.72-3.042 23.333 4.867 8 15z';
    const HEART_SOLID_PATH = 'M8 1.314C12.438-3.248 23.534 4.735 8 15-7.534 4.736 3.562-3.248 8 1.314z';
    const fancyDescImages = [ 'https://files.catbox.moe/0g3kqu.jpg', 'https://files.catbox.moe/kjan2x.gif', 'https://files.catbox.moe/u1r4x3.jpg', 'https://files.catbox.moe/gvy4kh.jpg', 'https://files.catbox.moe/n94ztu.jpg', 'https://files.catbox.moe/tyd6yh.jpeg', 'https://files.catbox.moe/5r4ldw.jpeg', 'https://files.catbox.moe/d5b7k6.jpg', 'https://files.catbox.moe/0yrhh6.jpg', 'https://files.catbox.moe/8mjvdg.jpg', 'https://files.catbox.moe/fvidas.jpg', 'https://files.catbox.moe/q6so2i.jpg', 'https://files.catbox.moe/5a96cp.jpg', 'https://files.catbox.moe/0mp6h0.jpg', 'https://files.catbox.moe/epcn03.jpg', 'https://files.catbox.moe/7jzdp7.jpg', 'https://files.catbox.moe/jrmu6w.jpg', 'https://files.catbox.moe/c0bwhn.jpg', 'https://files.catbox.moe/0blxme.jpg', 'https://files.catbox.moe/qicobr.jpg' ];
