    ];
    let assignedNpcAvatars = {};
    const mainCharacterNames = Object.keys(CHARACTER_AVATARS).sort((a, b) => b.length - a.length);
    function getElement(selector, context = document) { return context.querySelector(selector); }
    function getElementById(id) { return document.getElementById(id); }
    function getAvatarUrl(userName, avatarElement) {
         const dataName = avatarElement ? avatarElement.getAttribute('data-username') : null;
         const nameToLookup = dataName || userName;
         if (!nameToLookup) return null;
         for (const mainCharacterName of mainCharacterNames) {
             if (nameToLookup.includes(mainCharacterName)) {
                 return CHARACTER_AVATARS[mainCharacterName];
             }
         }
         if (nameToLookup.includes(CURRENT_USER_NAME)) {
            return null;
         }
         if (!assignedNpcAvatars[nameToLookup]) {
             assignedNpcAvatars[nameToLookup] = NPC_AVATARS[Math.floor(Math.random() * NPC_AVATARS.length)];
         }
         return assignedNpcAvatars[nameToLookup];
     }
    function setAvatarStyle(avatarElement, userName) {
         const avatarUrl = getAvatarUrl(userName, avatarElement);
         if (avatarUrl) {
             avatarElement.style.backgroundImage = `url('${avatarUrl}')`;
             avatarElement.classList.remove('user_avatar', 'avatar');
         } else {
             avatarElement.style.backgroundImage = '';
             avatarElement.classList.add('user_avatar', 'avatar');
         }
     }
    function showPublishModal() { const backdrop = getElementById('publish-modal-backdrop'); const modal = getElementById('publish-modal'); if (backdrop && modal) { backdrop.style.display = 'block'; modal.style.display = 'block'; getElementById('publish-text').focus();} }
    function hidePublishModal() { const backdrop = getElementById('publish-modal-backdrop'); const modal = getElementById('publish-modal'); if (backdrop && modal) { backdrop.style.display = 'none'; modal.style.display = 'none';} const textInput = getElementById('publish-text'); const imagesInput = getElementById('publish-images'); if (textInput) textInput.value = ''; if (imagesInput) imagesInput.value = ''; }
    function showCommentModal(postAuthorName, commentListId) { const titleElement = getElementById('comment-modal-title'); const postAuthorInput = getElementById('comment-modal-post-author-name'); const listIdInput = getElementById('comment-modal-target-list-id'); const textElement = getElementById('comment-modal-text'); if (titleElement) titleElement.textContent = `回复 ${postAuthorName}：`; if (postAuthorInput) postAuthorInput.value = postAuthorName; if (listIdInput) listIdInput.value = commentListId; if (textElement) textElement.value = ''; const backdrop = getElementById('comment-modal-backdrop'); const modal = getElementById('comment-modal'); if (backdrop && modal) { backdrop.style.display = 'block'; modal.style.display = 'block'; if (textElement) textElement.focus(); } }
    function hideCommentModal() { const backdrop = getElementById('comment-modal-backdrop'); const modal = getElementById('comment-modal'); if (backdrop && modal) { backdrop.style.display = 'none'; modal.style.display = 'none'; } const textElement = getElementById('comment-modal-text'); if (textElement) textElement.value = ''; }
    function handleCommentSubmit() { const commentTextElement = getElementById('comment-modal-text'); const commentText = commentTextElement ? commentTextElement.value.trim() : ""; const postAuthorName = getElementById('comment-modal-post-author-name').value; const commentListId = getElementById('comment-modal-target-list-id').value; if (commentText !== "") { displayComment(commentListId, CURRENT_USER_NAME, null, commentText); const commandString = `/send 回复${postAuthorName}的朋友圈：“${commentText}”|/trigger`; const canTriggerSlash = typeof triggerSlash === 'function'; if (canTriggerSlash) { try { triggerSlash(commandString); } catch (e) { console.error("Error calling triggerSlash:", e); } } else { navigator.clipboard.writeText(commandString).then(() => {}).catch(err => { console.error("Clipboard write failed:", err); }); } try { const s = new Audio('https://assets.mixkit.co/active_storage/sfx/2570/2570-preview.mp3'); s.volume=0.5; s.play().catch(()=>{}); } catch(e){} } hideCommentModal(); }
    function toggleLike(buttonElement, userName, likeListId) { if (!buttonElement || !userName || !likeListId) return; const likeListContainer = getElementById(likeListId); if (!likeListContainer) { return; } const likeSpan = getElement('span', likeListContainer); if (!likeSpan) { return; } const svgElement = getElement('svg', buttonElement); const svgPath = svgElement ? getElement('path', svgElement) : null; const buttonTextSpan = getElement('span', buttonElement); if (!svgElement || !svgPath || !buttonTextSpan) { return; } const currentLikes = likeSpan.textContent.trim(); const userString = userName; const userCheckPattern = new RegExp(`(?:^|,\\s*)${userString.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&')}(?:,\\s*|$)`); let alreadyLiked = userCheckPattern.test(currentLikes); if (!alreadyLiked) { if (currentLikes === "") { likeSpan.textContent = userString; } else { likeSpan.textContent += `, ${userString}`; } svgPath.setAttribute('d', HEART_SOLID_PATH); svgElement.setAttribute('fill', '#576b95'); buttonTextSpan.textContent = '取消'; try { const s = new Audio('https://files.catbox.moe/gb0so5.mp3'); s.volume = 0.4; s.play().catch(()=>{}); } catch (e) {} } else { let namesArray = currentLikes.split(',').map(name => name.trim()).filter(name => name !== ""); namesArray = namesArray.filter(name => name !== userString); likeSpan.textContent = namesArray.join(', '); svgPath.setAttribute('d', HEART_HOLLOW_PATH); svgElement.setAttribute('fill', 'currentColor'); buttonTextSpan.textContent = '喜欢'; } updateInteractionSectionVisibility(likeSpan); }
    function displayComment(commentListId, commenterName, repliedToName, commentText) { const commentList = getElementById(commentListId); if (!commentList) { return;} const newCommentDiv = document.createElement('div'); newCommentDiv.classList.add('comment'); const authorLink = document.createElement('a'); authorLink.href = '#'; authorLink.classList.add('comment-author'); authorLink.textContent = commenterName; newCommentDiv.appendChild(authorLink); const colonText = document.createTextNode(': '); newCommentDiv.appendChild(colonText); const commentSpan = document.createElement('span'); commentSpan.classList.add('comment-text'); let processedText = commentText.replace(/@(\S+)/g, '<strong>@{{user}}</strong>'); processedText = processedText.replace(/\[([^\]\s]+)\]/g, ' {{user}} '); processedText = processedText.replace(/\n/g, '<br>'); commentSpan.innerHTML = processedText; newCommentDiv.appendChild(commentSpan); commentList.appendChild(newCommentDiv); updateInteractionSectionVisibility(commentList); }
    function updateInteractionSectionVisibility(elementInsideInteraction) { if (!elementInsideInteraction) return; const interactionSection = elementInsideInteraction.closest('.item-interactions'); if (!interactionSection) return; const likeSection = getElement('.likes-section', interactionSection); const commentSection = getElement('.comments-section', interactionSection); const likeSpan = likeSection ? getElement('span', likeSection) : null; const likesExist = likeSpan ? likeSpan.textContent.trim() !== "" : false; const commentsExist = commentSection ? (getElement('.comment', commentSection) !== null) : false; interactionSection.classList.toggle('active', likesExist || commentsExist); if (likeSection) { likeSection.classList.toggle('active', likesExist); } if (commentSection) { commentSection.classList.toggle('active', commentsExist); } }
     function buildNewPostHTML(userName, postText, mediaInputsArray, timestampString) {
        const uniquePostIdSuffix = Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
        const postId = `feed-item-${uniquePostIdSuffix}`;
        const likeListId = `like-list-${uniquePostIdSuffix}`;
        const commentListId = `comment-list-${uniquePostIdSuffix}`;
        let avatarClasses = "item-avatar";
        let avatarStyle = "";
        const avatarUrl = getAvatarUrl(userName);
        if (avatarUrl) {
            avatarStyle = `style="background-image: url('${avatarUrl}');"`;
        } else {
            avatarClasses += " user_avatar avatar";
        }
        const avatarHTML = `<div class="${avatarClasses}" ${avatarStyle} data-username="${userName}"></div>`;
        let mediaHTML = '';
        const firstUIDescription = mediaInputsArray.find(item => item.type === 'description');
        const uiImages = mediaInputsArray.filter(item => item.type === 'image');
        if (uiImages.length === 0 && firstUIDescription) {
             const descriptionTextUI = firstUIDescription.content;
             const randomBgImage = fancyDescImages[Math.floor(Math.random() * fancyDescImages.length)];
              mediaHTML = `<div class="random-image-container" style="background: url('${randomBgImage}') center / cover;">
