   function handlePublish() {
        const textInput = getElementById('publish-text');
        const imagesInput = getElementById('publish-images');
        if (!textInput || !imagesInput) return;
        const postText = textInput.value.trim();
        const mediaInputsString = imagesInput.value.trim();
        const userName = CURRENT_USER_NAME;
        if (postText === "" && mediaInputsString === "") { return; }
        let processedMediaInputsForUI = [];
        let descriptionForFormat = "无";
        if (mediaInputsString !== '') {
             const rawMediaInputs = mediaInputsString.split(/[\n,]+/).map(input => input.trim()).filter(input => input !== '');
             if (rawMediaInputs.length > 0) { descriptionForFormat = rawMediaInputs[0]; }
             rawMediaInputs.forEach(input => {
                   if (input.toLowerCase().startsWith('http://') || input.toLowerCase().startsWith('https://')) {
                       processedMediaInputsForUI.push({ type: 'image', content: input });
                   } else {
                       processedMediaInputsForUI.push({ type: 'description', content: input });
                   }
             });
        }
        const newPostHTML = buildNewPostHTML(userName, postText, processedMediaInputsForUI, "刚刚");
        const feedListContainer = getElementById('feed-list-container');
        if (feedListContainer) {
             feedListContainer.insertAdjacentHTML('afterbegin', newPostHTML);
             const newPostElement = feedListContainer.firstChild;
             if(newPostElement) { const interactionSection = getElement('.item-interactions', newPostElement); if(interactionSection) { updateInteractionSectionVisibility(interactionSection); } }
        } else { console.error("Cannot find #feed-list-container!"); }
        const formattedPostString = `<朋友圈>\n[发布:${userName}]: ${postText} {{${descriptionForFormat}}}\n[点赞]: \n</朋友圈>`;
        const canTriggerSlash = typeof triggerSlash === 'function';
        if (canTriggerSlash) {
            try { triggerSlash(`/send ${formattedPostString}|/trigger`); }
            catch (e) { console.error("Error calling triggerSlash:", e); navigator.clipboard.writeText(formattedPostString).catch(err => { console.error("Clipboard write failed:", err); }); }
        } else {
             navigator.clipboard.writeText(formattedPostString).catch(err => { console.error("Clipboard write failed:", err); });
        }
         try { const s = new Audio('https://files.catbox.moe/gvk2af.mp3'); s.volume=0.5; s.play().catch(()=>{}); } catch(e){}
        hidePublishModal();
   }
    document.addEventListener('DOMContentLoaded', function() {
        assignedNpcAvatars = {};
        document.querySelectorAll('.feed-item').forEach(item => {
            const avatarElement = getElement('.item-avatar', item);
            if (avatarElement) {
                const userNameFromData = avatarElement.getAttribute('data-username');
                if (userNameFromData) {
                    setAvatarStyle(avatarElement, userNameFromData);
                } else {
                    const usernameElement = getElement('.item-username', item);
                    if (usernameElement) {
                        const userNameFromText = usernameElement.textContent.trim();
                        setAvatarStyle(avatarElement, userNameFromText);
                    }
                }
            }
            const likeButton = item.querySelector('.action-button[onclick*="toggleLike"]');
            const likeListContainer = item.querySelector('.likes-section');
            if (likeButton && likeListContainer) {
                const likeSpan = getElement('span', likeListContainer);
                if(likeSpan){
                    const currentLikes = likeSpan.textContent.trim();
                    const userCheckPattern = new RegExp(`(?:^|,\\s*)${CURRENT_USER_NAME.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&')}(?:,\\s*|$)`);
                    const initiallyLiked = userCheckPattern.test(currentLikes);
                    const svgElement = getElement('svg', likeButton);
                    const svgPath = svgElement ? getElement('path', svgElement) : null;
                    const buttonTextSpan = getElement('span', likeButton);
                    if (initiallyLiked && svgPath && buttonTextSpan) {
                        svgPath.setAttribute('d', HEART_SOLID_PATH);
                        svgElement.setAttribute('fill', '#576b95');
                        buttonTextSpan.textContent = '取消';
                    }
                }
            }
            const interactionSection = getElement('.item-interactions', item);
            if(interactionSection) {
                updateInteractionSectionVisibility(interactionSection);
            }
        });
        const initialPublishModal = getElementById('publish-modal'); if(initialPublishModal && initialPublishModal.style.display !== 'none') { hidePublishModal(); }
        const initialCommentModal = getElementById('comment-modal'); if(initialCommentModal && initialCommentModal.style.display !== 'none') { hideCommentModal(); }
    });
</script>
</body>
</html>
