async function characterPrompt() {
    const message = getChatMessages(1)[0];
    const primary = getCharWorldbookNames().primary;
    console.log("检测到消息发送，开始执行精神小妹角色判定逻辑..." + message.message);
    //如果message不存在或不包含<user设定>标签，则结束执行
    if (!message || !message.message.includes("<user设定>")) {
        console.log("消息内容不包含<user设定>标签，回归默认值");
        const defaultWorldbook = await getWorldbook(primary);
        defaultWorldbook.map(entry => {
            if (entry.name === "user设定（别动！）") {
                entry.content = `<user设定>
{{user}}性能力设定：
-从小睾酮素分泌易于常人，因此具有极强的性能力
-阴茎巨大，长20厘米，粗6厘米
