- 相貌普通，平平无奇，5分颜值
- 社交账号ID：【{{user}}】[根据{{user}}名字、性格、生成一个有意思的网名]

公开资料：
- CCPC大学生程序设计竞赛银奖
- 广州市“羊城之拳”男子中量级格斗锦标赛·铜牌获得者
- 华南理工大学学历
- 周叔：省书记，本人永远不出场，只有<user>涉及到警察才会通过电话出现，周叔就会通过某种渠道获得消息，从而层层施压帮<user>解决问题（这段过程是绝密的，外部表现只将<user>塑造成一个普通人形象），否则永远无法被查，永远不会出现。
</user设定>`;
            }
        });
        await replaceWorldbook(primary, defaultWorldbook);
        return;
    }
    const worldbook = await getWorldbook(primary);
    worldbook.map(entry => {
        if (entry.name === "user设定（别动！）") {
            console.log("开始处理世界观条目");
            //仅获取message.message中 <user设定></user设定> 里的内容，包括<user设定>标签本身
            const userSettingsMatch = message.message.match(/<user设定>([\s\S]*?)<\/user设定>/);
            if (userSettingsMatch) {
                const jsonData = JSON.parse(userSettingsMatch[1]);
                const otherSettings = jsonData["其他设定"] || [];
                const others = otherSettings["补充信息"] || [];
                //如果存在性能力设定，则提取出来，否则不显示
                const sexPower = otherSettings["性能力设定"] || [];
                // 组装为文本格式，如果存在性能力设定，则提取出来，否则不显示
                let formatted =
                    `<user设定>\n` +
                    `{{user}}其他设定：\n` + (others.length ? others.map(i => `${i}`).join("\n") : "（无）");
                if (sexPower.length) {
                    formatted.concat(`\n\n性能力设定：\n` + sexPower.map(i => `${i}`).join("\n"));
                }

                formatted.concat(`\n</user设定>`);
                entry.content = formatted;
                console.log("最终提取结果:\n" + formatted);
            } else {
                console.log("未找到<user设定>标签内容，保持原有世界观条目不变。");
            }
            console.log("处理完成，新的世界观条目内容为: " + entry.content);
        }
    })
    await replaceWorldbook(primary, worldbook);

}

