                                        <li class="info-list-item"><strong>下次生理期:</strong> ${physiologicalData['距离下次生理期天数'] === -1 ? '无 (怀孕中)' : `还剩 ${physiologicalData['距离下次生理期天数']} 天`}</li>
                                        <li class="info-list-item"><strong>持续时间:</strong> ${physiologicalData['生理期持续天数'] || 'N/A'} 天</li>
                                        <li class="info-list-item"><strong>怀孕状态:</strong> ${physiologicalData['怀孕状态'] || 'N/A'}</li>
                                        <li class="info-list-item"><strong>怀孕天数:</strong> ${physiologicalData['怀孕天数'] || 'N/A'}</li>
                                        <li class="info-list-item"><strong>安全期:</strong> ${physiologicalData['安全期'] ? '是' : '否'}</li>
                                        <li class="info-list-item"><strong>堕胎次数:</strong> ${physiologicalData['堕胎次数']}</li>
                                        <li class="info-list-item"><strong>生育次数:</strong> ${physiologicalData['生育次数']}</li>
                                    </ul>
                                </details>
                            </div>
                        </div>
                    </div>`;

                modalContainer.appendChild(modalDiv);
                void modalDiv.offsetWidth;
                modalDiv.classList.add('active');
                modalDiv.addEventListener('click', function (e) {
                    if (e.target === this) {
                        this.classList.remove('active');
                        this.addEventListener('transitionend', () => this.remove(), { once: true });
                    }
                });
            }

            function renderCycle(waitForData) {
                setLoadingState("正在等待ERA数据加载...");
                try {
                    const data = waitForData;
                    if (data && data['世界'] && data['user']) {
                        const worldData = data['世界'] || {};
                        const mainInfoData = data['user'] || {};
                        const allCharacters = data['精神小妹'] ? Object.values(data['精神小妹']) : [];
                        renderMainPanel(mainInfoData, worldData);
                        renderBriefCards(allCharacters);
                    } else {
                        throw new Error("未能获取到完整数据。");
                        setFailureState();
                    }
                } catch (error) {
                    console.error(error.message);
                    setFailureState();
                }
            }

            function setLoadingState(message) {
                appContainer.innerHTML = `<div style="text-align: center; padding: 50px; font-family: var(--font-main); color: var(--primary-glow);">${message}</div>`;
            }

            function setFailureState() {
                appContainer.innerHTML = `
                    <div style="text-align: center; padding: 50px 20px; font-family: var(--font-main); color: #ff4d4d;">
                        ERA系统连接失败...<br><small style="color:var(--text-secondary);font-size:0.8em;font-weight:400;">有可能是ERA变量输出格式不正确，检查一下ERA变量，或者从ROLL</small>
                    </div>
                    <div style="text-align:center; padding-bottom: 20px;">
                        <button id="retry-button">↻ 重试连接</button>
                    </div>`;
                const retryButton = document.getElementById('retry-button');
                if (retryButton) {
                    retryButton.onclick = () => {
                        retryButton.textContent = '↻ 正在重试...';
                        retryButton.disabled = true;
                        eventEmit('era:requestWriteDone');
                    };
                }
            }

            eventOn('era:writeDone', (detail) => {
                console.log('ERA:writeDone event received:', detail);
                if (detail && detail.statWithoutMeta) {
                    renderCycle(detail.statWithoutMeta);
                } else {
                    console.warn('era:writeDone event did not contain expected data structure.');
                    // 可以在这里调用失败处理
                    setFailureState();
                }
            });


            console.log('Requesting initial ERA variables...');
            eventEmit('era:requestWriteDone');
        });

    </script>
</body>

</html>
