        const userName = CURRENT_USER_NAME;
        if (postText === "" && mediaInputsString === "") { return; }
        let processedMediaInputsForUI = [];
        let descriptionForFormat = "无";
        if (mediaInputsString !== '') {
             const rawMediaInputs = mediaInputsString.split(/[\n,]+/).map(input => input.trim()).filter(input => input !== '');
             if (rawMediaInputs.length > 0) { descriptionForFormat = rawMediaInputs[0]; }
             rawMediaInputs.forEach(input => {
                   if (input.toLowerCase().startsWith('http://') || input.toLowerCase().startsWith('https://')) {
                       processedMediaInputsForUI.push({ type: 'image', content: input });
                   } else {
                       processedMediaInputsForUI.push({ type: 'description', content: input });
                   }
             });
        }
        const newPostHTML = buildNewPostHTML(userName, postText, processedMediaInputsForUI, "刚刚");
        const feedListContainer = getElementById('feed-list-container');
        if (feedListContainer) {
             feedListContainer.insertAdjacentHTML('afterbegin', newPostHTML);
             const newPostElement = feedListContainer.firstChild;
             if(newPostElement) { const interactionSection = getElement('.item-interactions', newPostElement); if(interactionSection) { updateInteractionSectionVisibility(interactionSection); } }
        } else { console.error("Cannot find #feed-list-container!"); }
        const formattedPostString = `<朋友圈>\n[发布:${userName}]: ${postText} {{${descriptionForFormat}}}\n[点赞]: \n</朋友圈>`;
        const canTriggerSlash = typeof triggerSlash === 'function';
        if (canTriggerSlash) {
            try { triggerSlash(`/send ${formattedPostString}|/trigger`); }
            catch (e) { console.error("Error calling triggerSlash:", e); navigator.clipboard.writeText(formattedPostString).catch(err => { console.error("Clipboard write failed:", err); }); }
        } else {
             navigator.clipboard.writeText(formattedPostString).catch(err => { console.error("Clipboard write failed:", err); });
        }
         try { const s = new Audio('https://files.catbox.moe/gvk2af.mp3'); s.volume=0.5; s.play().catch(()=>{}); } catch(e){}
        hidePublishModal();
   }
    document.addEventListener('DOMContentLoaded', function() {
