                    setAvatarStyle(avatarElement, userNameFromData);
                } else {
                    const usernameElement = getElement('.item-username', item);
                    if (usernameElement) {
                        const userNameFromText = usernameElement.textContent.trim();
                        setAvatarStyle(avatarElement, userNameFromText);
                    }
                }
            }
            const likeButton = item.querySelector('.action-button[onclick*="toggleLike"]');
            const likeListContainer = item.querySelector('.likes-section');
            if (likeButton && likeListContainer) {
                const likeSpan = getElement('span', likeListContainer);
                if(likeSpan){
                    const currentLikes = likeSpan.textContent.trim();
                    const userCheckPattern = new RegExp(`(?:^|,\\s*)${CURRENT_USER_NAME.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&')}(?:,\\s*|$)`);
                    const initiallyLiked = userCheckPattern.test(currentLikes);
                    const svgElement = getElement('svg', likeButton);
                    const svgPath = svgElement ? getElement('path', svgElement) : null;
                    const buttonTextSpan = getElement('span', likeButton);
                    if (initiallyLiked && svgPath && buttonTextSpan) {
                        svgPath.setAttribute('d', HEART_SOLID_PATH);
                        svgElement.setAttribute('fill', '#576b95');
                        buttonTextSpan.textContent = '取消';
                    }
                }
            }
            const interactionSection = getElement('.item-interactions', item);
            if(interactionSection) {
                updateInteractionSectionVisibility(interactionSection);
            }
        });
        const initialPublishModal = getElementById('publish-modal'); if(initialPublishModal && initialPublishModal.style.display !== 'none') { hidePublishModal(); }
        const initialCommentModal = getElementById('comment-modal'); if(initialCommentModal && initialCommentModal.style.display !== 'none') { hideCommentModal(); }
    });
</script>
</body>
</html>
