<div class="danmaku-container">
    <div class="danmaku-header">
        <div class="live-indicator">
            <div class="pulse-dot"></div>
            <span class="live-text">LIVE</span>
            <span class="viewer-count">$1</span>
        </div>
        <div class="sc-ticker-channel">
            <div class="sc-ticker-content"></div>
        </div>
    </div>
    <div class="danmaku-scroll-area">
        <div class="danmaku-wrapper"></div>
    </div>
</div>

<script>
    (function() {
        const wrapper = document.querySelector('.danmaku-wrapper');
        const scTicker = document.querySelector('.sc-ticker-content');
        const rawText = `$2`;
        const lines = rawText.split(/\\n|\n/).filter(line => line.trim() !== '');
        const scRegex = /\[((?:￥|\$|€)[\d,.]+)\|([^|\]]+)\]:(.+)/;
        const noticeRegex = /\[系统通知\]:(.+)/;
        const dmRegex = /\[([^|\]\n]+)\]:(.+)/;

        let verticalContentHtml = '';
        let scContentHtml = '';

        lines.forEach(line => {
            const content = line.trim();
            const scMatch = content.match(scRegex);
            const noticeMatch = content.match(noticeRegex);
            const dmMatch = content.match(dmRegex);

            if (scMatch) {
                scContentHtml += `<span class="sc-ticker-item"><span class="sc-item-static">感谢</span><span class="sc-item-name">${scMatch[2]}</span><span class="sc-item-static">打赏</span><span class="sc-item-amount">${scMatch[1]}</span><span class="sc-item-static">:</span><span class="sc-item-message">${scMatch[3]}</span></span>`;
            } else if (noticeMatch) {
                verticalContentHtml += `<div class="danmaku-base system-notice"><span>📢 [系统通知]: ${noticeMatch[1]}</span></div>`;
            } else if (dmMatch) {
                verticalContentHtml += `<div class="danmaku-base danmaku-item"><span class="name">${dmMatch[1]}:</span><span class="message">${dmMatch[2]}</span></div>`;
            }
        });

        if (scTicker && scContentHtml) {
            scTicker.innerHTML = `<div>${scContentHtml}</div><div>${scContentHtml}</div>`;
        }

        if (wrapper && verticalContentHtml) {
            wrapper.innerHTML = `<div>${verticalContentHtml}</div><div>${verticalContentHtml}</div>`;
        }
    })();
</script>

</body>
</html>
